example_code:
# Embedding: direcciones anidadas dentro del usuario, un solo fetch
usuario_embedded = {
    "nombre": "ana",
    "direcciones": [
        {"ciudad": "Madrid", "cp": "28001"},
        {"ciudad": "Lima", "cp": "15001"},
    ],
}

# Referencing: el usuario guarda solo IDs, las direcciones viven aparte
usuarios_ref = {"u1": {"nombre": "ana", "direccion_ids": ["d1", "d2"]}}
direcciones_ref = {
    "d1": {"ciudad": "Madrid", "cp": "28001"},
    "d2": {"ciudad": "Lima", "cp": "15001"},
}

def fetch_embedded(usuario):
    return usuario["direcciones"]  # una sola lectura

def fetch_referenciado(usuario_id):
    usuario = usuarios_ref[usuario_id]
    return [direcciones_ref[did] for did in usuario["direccion_ids"]]  # lookups extra

print(f"Embedding, un fetch: {fetch_embedded(usuario_embedded)}")
print(f"Referencing, {len(usuarios_ref['u1']['direccion_ids'])} lookups extra: {fetch_referenciado('u1')}")

# actualizar una direccion compartida es mas facil con referencing
direcciones_ref["d1"]["cp"] = "28002"
print(f"Tras actualizar d1 una vez, u1 ve el cambio: {fetch_referenciado('u1')[0]}")

